<template>
  <main class="homework-page">
    <header class="page-head"><div><p class="eyebrow">学生学习中心</p><h2>📝 我的作业</h2><p>完成后提交每道题；老师开放解析后，只显示你已提交题目的答案和解析。</p></div><button class="ghost" @click="loadAssignments" :disabled="loading">{{ loading ? '刷新中…' : '刷新作业' }}</button></header>
    <p v-if="error" class="error">{{ error }}</p>
    <div v-if="!assignments.length && !loading" class="empty state">老师还没有布置课后作业。</div>
    <section v-else class="assignment-list"><button v-for="item in assignments" :key="item.id" class="assignment-card" :class="{ active: paper?.id === item.id }" @click="openAssignment(item.id)"><b>{{ item.title }}</b><span>{{ item.submittedCount }}/{{ item.total }} 道题已提交</span><small v-if="item.analysisReleasedAt" class="released">总分 {{ item.score }}/{{ item.maxScore }} · 解析已开放</small><small v-else>等待完成或老师开放解析</small></button></section>

    <section v-if="paper" class="paper-panel">
      <header class="paper-head"><div><h3>{{ paper.title }}</h3><p>{{ paper.submittedCount }}/{{ paper.total }} 道题已提交<span v-if="paper.deadline"> · 截止 {{ paper.deadline }}</span></p></div><button class="ghost" @click="paper = null">返回作业列表</button></header>
      <div v-if="paper.analysisReleasedAt" class="score-card"><strong>总得分 {{ paper.score }}/{{ paper.maxScore }} 分</strong><span>已开放已提交题目的解析</span></div>
      <nav class="question-nav"><button v-for="question in paper.questions" :key="question.id" :class="{ active: question.id === currentId, done: isSubmitted(question.id), wrong: isWrong(question.id) }" @click="currentId = question.id">{{ question.label }}</button></nav>
      <article v-if="currentQuestion" class="question-card">
        <div class="question-title"><h3>{{ currentQuestion.label }}</h3><span>{{ currentQuestion.tags.join(' · ') }}</span></div>
        <div v-if="isChoice(currentQuestion)" class="choice-question"><div class="markdown" v-html="renderMd(currentQuestion.question)"></div><div class="options"><button v-for="(text,key) in currentQuestion.options" :key="key" :class="optionClass(currentQuestion.id,key,currentQuestion.answer)" :disabled="lockedCurrent" @click="selectOption(currentQuestion.id,key,false)"><b>{{ key }}</b><span v-html="renderInline(text)"></span></button></div></div>
        <div v-else class="program-question"><div class="markdown" v-html="renderMd(currentQuestion.statement || currentQuestion.description)"></div><section v-for="part in currentQuestion.questions" :key="part.id" class="part"><h4>第 {{ part.number }} 小题</h4><div class="markdown" v-html="renderMd(part.text)"></div><div class="options"><button v-for="(text,key) in part.options" :key="key" :class="optionClass(part.id,key,part.answers)" :disabled="lockedCurrent" @click="selectOption(part.id,key,part.multiple)"><b>{{ key }}</b><span v-html="renderInline(text)"></span></button></div><div v-if="revealedCurrent" class="part-answer"><b>答案：{{ (part.answers || []).join('、') }}</b><span v-if="part.explanation">{{ part.explanation }}</span></div></section></div>
        <div class="question-actions"><span v-if="submittedCurrent">{{ paper.analysisReleasedAt ? `得分 ${currentSubmission.score}/${currentSubmission.maxScore}` : '已提交，等待解析' }}</span><span v-else>选择后会自动保存草稿</span><div><button class="secondary" :disabled="busy || lockedCurrent" @click="saveCurrent">保存草稿</button><button class="primary" :disabled="busy || lockedCurrent || !canSubmit" @click="submitCurrent">{{ busy ? '提交中…' : (submittedCurrent ? '修改并提交' : '提交本题') }}</button></div></div>
        <div v-if="revealedCurrent" class="answer-box"><b :class="isWrong(currentId) ? 'bad' : 'ok'">{{ isWrong(currentId) ? '本题有错误' : '本题正确' }}</b><p v-if="isChoice(currentQuestion)">参考答案：{{ currentQuestion.answer }}</p><div v-if="currentQuestion.explanation" class="markdown" v-html="renderMd(currentQuestion.explanation)"></div></div>
      </article>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { authFetch } from '../utils/auth';
import { renderCspMarkdown as renderMd, renderCspInline as renderInline } from '../utils/cspMarkdown';

const assignments = ref([]); const paper = ref(null); const currentId = ref(''); const drafts = ref({}); const loading = ref(false); const busy = ref(false); const error = ref('');
let refreshTimer = null; let saveTimer = null;
function readJson(response) { return response.text().then(text => { let data = {}; try { data = text ? JSON.parse(text) : {}; } catch { throw new Error(text.startsWith('<') ? '服务器返回了网页，请检查后端是否已更新' : '服务器返回的数据格式不正确'); } if (!response.ok) throw new Error(data.error || '请求失败'); return data; }); }
function isChoice(question) { return ['choice', 'judgment'].includes(question?.type); }
const currentQuestion = computed(() => paper.value?.questions?.find(item => item.id === currentId.value) || null);
const currentSubmission = computed(() => paper.value?.submissions?.[currentId.value] || { answers: {}, submitted: false });
const submittedCurrent = computed(() => Boolean(currentSubmission.value.submitted));
const revealedCurrent = computed(() => Boolean(paper.value?.analysisReleasedAt && submittedCurrent.value));
const lockedCurrent = computed(() => revealedCurrent.value);
const canSubmit = computed(() => { const q = currentQuestion.value; if (!q) return false; if (isChoice(q)) return selectedFor(q.id).length > 0; return q.questions.every(part => selectedFor(part.id).length > 0); });
function selectedFor(id) { const value = drafts.value[id]; return Array.isArray(value) ? value : value ? [value] : []; }
function isSubmitted(id) { return Boolean(paper.value?.submissions?.[id]?.submitted); }
function isWrong(id) { const item = paper.value?.submissions?.[id]; return Boolean(paper.value?.analysisReleasedAt && item?.submitted && Number(item.score) < Number(item.maxScore)); }
function optionClass(id, key, answer) { const selected = selectedFor(id).includes(key); const correct = Array.isArray(answer) ? answer.includes(key) : answer === key; return { selected, correct: revealedCurrent.value && correct, wrong: revealedCurrent.value && selected && !correct }; }
function selectOption(id, key, multiple) { const old = selectedFor(id); const next = multiple ? (old.includes(key) ? old.filter(item => item !== key) : [...old, key]) : [key]; drafts.value = { ...drafts.value, [id]: next }; scheduleSave(); }
function answersForCurrent() { if (!currentQuestion.value) return {}; if (isChoice(currentQuestion.value)) return { [currentQuestion.value.id]: selectedFor(currentQuestion.value.id) }; return Object.fromEntries(currentQuestion.value.questions.map(part => [part.id, selectedFor(part.id)])); }
async function saveCurrent() { if (!paper.value || !currentQuestion.value || lockedCurrent) return; try { await readJson(await authFetch(`/api/homework/student/assignments/${paper.value.id}/questions/${encodeURIComponent(currentQuestion.value.id)}`, { method: 'PUT', body: JSON.stringify({ answers: answersForCurrent() }) })); } catch (e) { error.value = e.message; } }
function scheduleSave() { clearTimeout(saveTimer); saveTimer = window.setTimeout(saveCurrent, 500); }
async function submitCurrent() { if (!paper.value || !currentQuestion.value) return; busy.value = true; error.value = ''; try { await saveCurrent(); await readJson(await authFetch(`/api/homework/student/assignments/${paper.value.id}/questions/${encodeURIComponent(currentQuestion.value.id)}/submit`, { method: 'POST', body: JSON.stringify({ answers: answersForCurrent() }) })); await openAssignment(paper.value.id); await loadAssignments({ silent: true }); window.dispatchEvent(new Event('homework-updated')); const next = paper.value.questions.find(q => !isSubmitted(q.id)); if (next) currentId.value = next.id; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function loadAssignments({ silent = false } = {}) { if (!silent) loading.value = true; try { assignments.value = await readJson(await authFetch('/api/homework/student/assignments')); } catch (e) { if (!silent) error.value = e.message; } finally { if (!silent) loading.value = false; } }
async function openAssignment(id) { error.value = ''; try { paper.value = await readJson(await authFetch(`/api/homework/student/assignments/${id}`)); const nextDrafts = {}; for (const submission of Object.values(paper.value.submissions || {})) Object.assign(nextDrafts, submission.answers || {}); drafts.value = nextDrafts; currentId.value = paper.value.questionIds.find(questionId => !isSubmitted(questionId)) || paper.value.questionIds[0] || ''; } catch (e) { error.value = e.message; } }
watch(currentId, () => { clearTimeout(saveTimer); });
onMounted(() => { loadAssignments(); refreshTimer = window.setInterval(() => { if (document.visibilityState === 'visible') loadAssignments({ silent: true }); }, 30000); });
onUnmounted(() => { if (refreshTimer) window.clearInterval(refreshTimer); clearTimeout(saveTimer); });
</script>

<style scoped>
.homework-page{height:100%;overflow:auto;padding:24px 28px 56px;background:#f7f9fc;color:#172033}.page-head,.paper-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.eyebrow{margin:0;color:#6366f1;font-size:13px;font-weight:800}.homework-page h2{margin:3px 0;color:#3730a3}.homework-page p{color:#64748b}.ghost,.secondary{padding:9px 13px;border:1px solid #c7d2fe;border-radius:8px;background:#fff;color:#3730a3;font:inherit;cursor:pointer}.assignment-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px;margin-top:18px}.assignment-card{display:flex;flex-direction:column;align-items:flex-start;gap:5px;padding:15px;border:1px solid #c7d2fe;border-radius:11px;background:#fff;color:#3730a3;text-align:left;cursor:pointer}.assignment-card.active{background:#eef2ff;border-color:#6366f1}.assignment-card span,.assignment-card small{color:#64748b}.released{color:#15803d!important;font-weight:800}.paper-panel{margin-top:18px;padding:20px;border:1px solid #dbe3f0;border-radius:14px;background:#fff}.score-card{display:flex;justify-content:space-between;align-items:center;margin:16px 0;padding:14px 16px;border:1px solid #a7f3d0;border-radius:10px;background:#f0fdf4;color:#166534}.score-card strong{font-size:20px}.question-nav{display:flex;flex-wrap:wrap;gap:7px;margin:16px 0;padding-bottom:14px;border-bottom:1px solid #e2e8f0}.question-nav button{padding:8px 10px;border:1px solid #c7d2fe;border-radius:8px;background:#eef2ff;color:#3730a3;cursor:pointer}.question-nav button.active{background:#4f46e5;color:#fff}.question-nav button.done{border-color:#86efac}.question-nav button.wrong{border-color:#fca5a5;color:#b91c1c}.question-title{display:flex;justify-content:space-between;gap:12px;align-items:center}.question-title span{color:#b45309;font-size:13px}.markdown{line-height:1.7}.options{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.options button{display:flex;gap:10px;align-items:center;padding:13px;border:1px solid #cbd5e1;border-radius:10px;background:#fff;color:#172033;text-align:left;font:inherit;cursor:pointer}.options button.selected{border-color:#6366f1;background:#eef2ff}.options button.correct{border-color:#22c55e;background:#f0fdf4}.options button.wrong{border-color:#ef4444;background:#fef2f2}.options button:disabled{cursor:default}.part{padding:13px 0;border-top:1px solid #eef2f7}.part-answer{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;padding:8px;background:#f0fdf4;color:#166534}.question-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:20px}.question-actions>div{display:flex;gap:8px}.primary{padding:10px 16px;border:0;border-radius:8px;background:#4f46e5;color:#fff;font-weight:800;cursor:pointer}.primary:disabled,.secondary:disabled,.ghost:disabled{opacity:.5;cursor:not-allowed}.answer-box{margin-top:18px;padding:14px;border-left:4px solid #22c55e;background:#f0fdf4}.ok{color:#15803d}.bad{color:#b91c1c}.empty{padding:26px;border-radius:10px;background:#fff;color:#64748b}.state{margin-top:18px}.error{color:#b91c1c}@media(max-width:800px){.homework-page{padding:18px 14px}.page-head,.paper-head,.question-title,.score-card{flex-direction:column;align-items:flex-start}.options{grid-template-columns:1fr}.question-actions{align-items:flex-start;flex-direction:column}}
</style>